(6823370, 1025777, 138630, '<td valign="top">Nice color and detail and, I''m sure, a very well equipped boat.  Love the sunburst.  Voted earlier.</td>', 'Nice color and detail and, I''m sure, a very well equipped boat.  Love the sunburst.  Voted earlier.', '2012-07-21 01:30:34.000000', NULL, 1),
(6823744, 1025755, 143116, '<td valign="top">I did not score this very high because the image is drab, lacks contrast and depth, in my view.  The boy''s hair blend with the laptop, and the frills on the lamp shade look to be the point of attention.</td>', 'I did not score this very high because the image is drab, lacks contrast and depth, in my view.  The boy''s hair blend with the laptop, and the frills on the lamp shade look to be the point of attention.', '2012-07-21 13:20:26.000000', NULL, 1),
